const fs=require("fs");const html=fs.readFileSync("index.html","utf8");
const js=html.split("<script>")[1].split("</script>")[0];
const cells=[];
const mkEl=()=>({classList:{add(){},remove(){}},dataset:{},addEventListener(){},select(){},focus(){},value:"",readOnly:false});
const document={getElementById:()=>mkEl(),createElement:()=>mkEl()};
const boardEl={appendChild(c){cells.push(c)}};
const statusEl={textContent:""};
let src=js.replace("const boardEl = document.getElementById(\x27board\x27);","").replace("const statusEl = document.getElementById(\x27status\x27);","").replace("const cells = [];","").replace("document.getElementById(\x27newBtn\x27).addEventListener(\x27click\x27, newPuzzle);","").replace(/document\.getElementById\(.checkBtn.\)\.addEventListener[^\n]*\n/,"").replace(/document\.getElementById\(.solveBtn.\)\.addEventListener[^\n]*\n/,"").replace(/\n\s*newPuzzle\(\);\s*$/,"");
const fn=new Function("document","boardEl","statusEl","cells",src+"\nreturn {newPuzzle,countSolutions,getSol:()=>solution,check,showSolution};");
const api=fn(document,boardEl,statusEl,cells);
for(let k=0;k<5;k++){
  const t0=Date.now(); api.newPuzzle();
  const puz=cells.map(c=>c.readOnly?+c.value:0);
  const givens=puz.filter(v=>v).length;
  const sol=api.getSol();
  const ok=sol.every((v,i)=>v>=1&&v<=9&&(!puz[i]||puz[i]===v));
  const uniq=api.countSolutions(puz.slice(),2);
  console.log("givens",givens,"unique",uniq,"consistent",ok,"ms",Date.now()-t0);
}
'

